    """
    Implements a phase oracle for the subset sum problem:
    Given a list a = [3, 14, 3, 13, 3], select elements whose sum equals 6.
    """
    # The selected elements that sum to 6 are:
    # - a[0] = 3
    # - a[0] + a[2] = 3 + 3 = 6

    # We need to implement the condition: sum of selected elements == 6
    # This corresponds to the subset {0}, {2}, or {0,2}

    # First, let's compute the sum of selected elements
    # We'll use the ancilla qubits to compute the sum

    # Define the values of the elements
    values = [3, 14, 3, 13, 3]

    # Compute the sum of selected elements
    # We'll use the first 3 ancilla qubits to represent the sum in binary
    sum_qubits = ancilla_qubits[:3]

    # Initialize sum to 0
