    for i, q in enumerate(sum_qubits):
        if (6 >> (2-i)) & 1:
            qc.x(q)

    # Apply multi-controlled Z gate to apply phase -1 if sum == 6
    qc.mcz(sum_qubits, flag_qubit)

    # Uncompute the target sum
    for i, q in enumerate(sum_qubits):
        if (6 >> (2-i)) & 1:
            qc.x(q)

    # Uncompute the sum
